/*
 * ============================================================
 * Predict one decision tree
 * ============================================================
 *
 * Returns:
 *   P(FALL)
 */

static inline float guardian360_predict_tree(
    const float *x,
    uint16_t tree_index
) {
    if (tree_index >= RF_NUM_TREES) {
        return 0.0f;
    }

    uint32_t base =
        pgm_read_dword(
            &rf_tree_offsets[tree_index]
        );

    uint16_t node_count =
        pgm_read_word(
            &rf_tree_node_counts[tree_index]
        );

    int16_t node = 0;

    while (true) {

        /*
         * Safety check.
         */

        if (
            node < 0 ||
            node >= (int16_t)node_count
        ) {
            return 0.0f;
        }

        uint32_t index =
            base + (uint32_t)node;

        /*
         * Read feature index.
         */

        uint8_t feature =
            pgm_read_byte(
                &rf_features[index]
            );

        /*
         * Leaf.
         */

        if (feature == RF_LEAF) {

            return pgm_read_float(
                &rf_leaf_probability[index]
            );
        }

        /*
         * Internal node.
         */

        float threshold =
            pgm_read_float(
                &rf_thresholds[index]
            );

        if (x[feature] <= threshold) {

            node =
                pgm_read_word(
                    &rf_left[index]
                );

        } else {

            node =
                pgm_read_word(
                    &rf_right[index]
                );
        }
    }
}


/*
 * ============================================================
 * Predict complete Random Forest
 * ============================================================
 *
 * Returns:
 *   Average probability of FALL.
 */

static inline float guardian360_predict_rf(
    const float *x
) {
    float probability_sum = 0.0f;

    for (
        uint16_t tree = 0;
        tree < RF_NUM_TREES;
        tree++
    ) {

        probability_sum +=
            guardian360_predict_tree(
                x,
                tree
            );
    }

    return (
        probability_sum /
        (float)RF_NUM_TREES
    );
}


/*
 * ============================================================
 * Final classification
 * ============================================================
 *
 * Returns:
 *   1 = FALL
 *   0 = NORMAL
 */

static inline uint8_t guardian360_predict(
    const float *x
) {
    float probability =
        guardian360_predict_rf(x);

    if (
        probability >=
        RF_FALL_THRESHOLD
    ) {
        return 1;
    }

    return 0;
}

